CREATE SCHEMA IF NOT EXISTS staging;
CREATE SCHEMA IF NOT EXISTS dw;
CREATE SCHEMA IF NOT EXISTS meta;

CREATE TABLE IF NOT EXISTS staging.orders (order_id text, customer_id text, order_status text, order_purchase_timestamp text, order_approved_at text, order_delivered_carrier_date text, order_delivered_customer_date text, order_estimated_delivery_date text);
CREATE TABLE IF NOT EXISTS staging.order_items (order_id text, order_item_id text, product_id text, seller_id text, shipping_limit_date text, price text, freight_value text);
CREATE TABLE IF NOT EXISTS staging.order_payments (order_id text, payment_sequential text, payment_type text, payment_installments text, payment_value text);
CREATE TABLE IF NOT EXISTS staging.order_reviews (review_id text, order_id text, review_score text, review_comment_title text, review_comment_message text, review_creation_date text, review_answer_timestamp text);
CREATE TABLE IF NOT EXISTS staging.products (product_id text, product_category_name text, product_name_lenght text, product_description_lenght text, product_photos_qty text, product_weight_g text, product_length_cm text, product_height_cm text, product_width_cm text);
CREATE TABLE IF NOT EXISTS staging.customers (customer_id text, customer_unique_id text, customer_zip_code_prefix text, customer_city text, customer_state text);
CREATE TABLE IF NOT EXISTS staging.sellers (seller_id text, seller_zip_code_prefix text, seller_city text, seller_state text);
CREATE TABLE IF NOT EXISTS staging.geolocation (geolocation_zip_code_prefix text, geolocation_lat text, geolocation_lng text, geolocation_city text, geolocation_state text);
CREATE TABLE IF NOT EXISTS staging.category_translation (product_category_name text, product_category_name_english text);

CREATE TABLE IF NOT EXISTS dw.dim_geolocation (geo_key bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, zip_prefix text UNIQUE, city text, state text, latitude double precision, longitude double precision, geo_point point);
CREATE INDEX IF NOT EXISTS ix_geo_point ON dw.dim_geolocation USING gist (geo_point);
CREATE TABLE IF NOT EXISTS dw.dim_product_category (category_key bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, category_name_pt text UNIQUE, category_name_en text NOT NULL);
CREATE TABLE IF NOT EXISTS dw.dim_customer (customer_key bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, customer_id text UNIQUE, customer_unique_id text, geo_key bigint REFERENCES dw.dim_geolocation, city text, state text);
CREATE INDEX IF NOT EXISTS ix_customer_unique ON dw.dim_customer(customer_unique_id);
CREATE TABLE IF NOT EXISTS dw.dim_seller (seller_key bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, seller_id text UNIQUE, geo_key bigint REFERENCES dw.dim_geolocation, city text, state text);
CREATE TABLE IF NOT EXISTS dw.dim_product (product_key bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, product_id text UNIQUE, category_key bigint REFERENCES dw.dim_product_category, weight_g numeric, length_cm numeric, height_cm numeric, width_cm numeric);
CREATE TABLE IF NOT EXISTS dw.dim_date (date_key integer PRIMARY KEY, calendar_date date UNIQUE, year integer, quarter integer, month integer, day integer);
CREATE TABLE IF NOT EXISTS dw.dim_order (order_key bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, order_id text UNIQUE, customer_key bigint REFERENCES dw.dim_customer, order_status text, purchase_timestamp timestamp, delivered_timestamp timestamp, estimated_delivery_timestamp timestamp, purchase_date_key integer REFERENCES dw.dim_date, delivered_date_key integer REFERENCES dw.dim_date, estimated_date_key integer REFERENCES dw.dim_date, is_delivered boolean, delivery_lead_time_days numeric, delivery_delay_days numeric, is_on_time boolean, latest_review_score integer);
CREATE INDEX IF NOT EXISTS ix_order_customer ON dw.dim_order(customer_key);
CREATE INDEX IF NOT EXISTS ix_order_purchase_date ON dw.dim_order(purchase_date_key);
CREATE TABLE IF NOT EXISTS dw.fact_order_items (order_item_key bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, order_key bigint NOT NULL REFERENCES dw.dim_order, order_item_id integer NOT NULL, product_key bigint REFERENCES dw.dim_product, seller_key bigint REFERENCES dw.dim_seller, price numeric(14,2), freight_value numeric(14,2), total_item_value numeric(14,2), UNIQUE(order_key,order_item_id));
CREATE INDEX IF NOT EXISTS ix_items_order ON dw.fact_order_items(order_key);
-- Reporting aggregates item amounts by order; INCLUDE allows an index-only scan.
CREATE INDEX IF NOT EXISTS ix_items_order_amounts ON dw.fact_order_items(order_key)
    INCLUDE (price, freight_value, total_item_value);
CREATE INDEX IF NOT EXISTS ix_items_product ON dw.fact_order_items(product_key);
CREATE INDEX IF NOT EXISTS ix_items_seller ON dw.fact_order_items(seller_key);
CREATE TABLE IF NOT EXISTS dw.fact_order_payments (payment_key bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, order_key bigint NOT NULL REFERENCES dw.dim_order, payment_sequential integer NOT NULL, payment_type text, payment_installments integer, payment_value numeric(14,2), UNIQUE(order_key,payment_sequential));
CREATE INDEX IF NOT EXISTS ix_payments_order ON dw.fact_order_payments(order_key);
CREATE TABLE IF NOT EXISTS dw.ml_order_risk_scores (order_id text PRIMARY KEY, late_probability numeric(8,6), predicted_late boolean, risk_band text, model_version text, scored_at timestamptz DEFAULT now());
CREATE TABLE IF NOT EXISTS dw.ml_customer_segments (customer_unique_id text PRIMARY KEY, cluster_id integer, segment_label text, model_version text, scored_at timestamptz DEFAULT now());
\ir 00_audit.sql
CREATE TABLE IF NOT EXISTS meta.data_dictionary (metric_name text PRIMARY KEY, definition text NOT NULL);
CREATE TABLE IF NOT EXISTS meta.ml_runs (run_id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, model_name text, run_at timestamptz DEFAULT now(), sample_size integer, metric_name text, metric_value numeric, notes text);

-- Upgrade existing warehouses as well as fresh installations.
ALTER TABLE dw.dim_product_category ADD COLUMN IF NOT EXISTS macro_department text NOT NULL DEFAULT 'Other';
CREATE TABLE IF NOT EXISTS meta.category_departments (
    category_name_pt text PRIMARY KEY,
    macro_department text NOT NULL CHECK (btrim(macro_department) <> '')
);

-- Preserve source grain when multiple missing orders map to order_key = 0.
ALTER TABLE dw.fact_order_items ADD COLUMN IF NOT EXISTS source_order_id text;
ALTER TABLE dw.fact_order_payments ADD COLUMN IF NOT EXISTS source_order_id text;
UPDATE dw.fact_order_items f SET source_order_id = o.order_id
FROM dw.dim_order o WHERE f.order_key = o.order_key AND f.source_order_id IS NULL;
UPDATE dw.fact_order_payments f SET source_order_id = o.order_id
FROM dw.dim_order o WHERE f.order_key = o.order_key AND f.source_order_id IS NULL;
ALTER TABLE dw.fact_order_items DROP CONSTRAINT IF EXISTS fact_order_items_order_key_order_item_id_key;
ALTER TABLE dw.fact_order_payments DROP CONSTRAINT IF EXISTS fact_order_payments_order_key_payment_sequential_key;
CREATE UNIQUE INDEX IF NOT EXISTS ix_items_source_grain ON dw.fact_order_items(source_order_id, order_item_id);
CREATE UNIQUE INDEX IF NOT EXISTS ix_payments_source_grain ON dw.fact_order_payments(source_order_id, payment_sequential);
